dtsPropsFor.Button:
/** Visual style. `default` is the crest-orange fill; `outline` and `secondary` sit on paper; `ghost` is bare; `link` is inline text. */
variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
/** `default` is 40px tall, `sm` 36px, `lg` 44px; `icon` is a 40px square for a lone icon. */
size?: "default" | "sm" | "lg" | "icon";
children?: React.ReactNode;
className?: string;
disabled?: boolean;
type?: "button" | "submit" | "reset";
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Badge:
/** `default` is a pale crest tint; `success` green, `warning` amber, `muted` grey, `destructive` red tint, `outline` bordered text. */
variant?: "default" | "success" | "warning" | "muted" | "destructive" | "outline";
children?: React.ReactNode;
className?: string;

dtsPropsFor.Card:
/** Compose with CardHeader, CardTitle, CardDescription and CardContent. Paper-white surface, 1px border, 12px radius. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.CardHeader:
/** Vertical stack with 24px padding; holds CardTitle and CardDescription. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.CardTitle:
/** Semibold title line inside CardHeader. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.CardDescription:
/** Muted 14px line under the title. */
children?: React.ReactNode;
className?: string;

dtsPropsFor.CardContent:
/** Body area, 24px side padding, no top padding (CardHeader supplies it). */
children?: React.ReactNode;
className?: string;

dtsPropsFor.Input:
/** Native input type; defaults to text. */
type?: string;
placeholder?: string;
id?: string;
name?: string;
value?: string;
defaultValue?: string;
disabled?: boolean;
required?: boolean;
className?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;

dtsPropsFor.Label:
/** The id of the control this labels. */
htmlFor?: string;
children?: React.ReactNode;
className?: string;

dtsPropsFor.Textarea:
placeholder?: string;
rows?: number;
id?: string;
name?: string;
value?: string;
defaultValue?: string;
disabled?: boolean;
required?: boolean;
className?: string;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;

dtsPropsFor.Select:
/** Native `<option>` elements. */
children?: React.ReactNode;
id?: string;
name?: string;
value?: string;
defaultValue?: string;
disabled?: boolean;
required?: boolean;
className?: string;
onChange?: React.ChangeEventHandler<HTMLSelectElement>;

dtsPropsFor.Avatar:
/** Full name; initials are drawn when there is no photo. */
name: string;
/** A photo URL; omit to show initials. */
photoUrl?: string | null;
/** sm 32px · md 36px · lg 48px · xl 80px. */
size?: "sm" | "md" | "lg" | "xl";
className?: string;

dtsPropsFor.PlayerToken:
/** Player name; initials are drawn when there is no photo. */
name: string;
photoUrl?: string | null;
/** Size the token with h-/w- classes; it has no default size. */
className?: string;
/** Drawn as a small badge on the token. */
shirtNumber?: number | null;

dtsPropsFor.TeamPicker:
id: string;
/** Form field name; repeated once per team when `multiple`. */
name: string;
/** Every team the reader may choose from; filtered in the browser as they type. */
teams: { id: string; name: string; ageGroup: string | null }[];
label?: string;
placeholder?: string;
/** Helper line under the field. */
help?: string;
required?: boolean;
/** Allow several teams, shown as chips. */
multiple?: boolean;

dtsPropsFor.SubmitButton:
/** Visible label. */
children?: React.ReactNode;
/** Screen-reader text while the surrounding form's action is pending. */
pendingLabel?: string;
variant?: "default" | "destructive" | "outline" | "secondary" | "ghost" | "link";
size?: "default" | "sm" | "lg" | "icon";
className?: string;
disabled?: boolean;

dtsPropsFor.PageHeader:
/** Page title, set in Oswald display caps. */
title: string;
subtitle?: string;
/** Right-aligned action, usually a Button. */
action?: React.ReactNode;
/** The way up: a chevron link above the title naming the parent list. */
back?: { href: string; label: string };
/** One-line header for screens whose content must fill a phone. */
compact?: boolean;

dtsPropsFor.EmptyState:
/** A lucide icon component, drawn in a circle above the title. */
icon?: React.ComponentType<{ className?: string }>;
title: string;
/** One sentence saying why the list is empty. */
children?: React.ReactNode;
/** The single thing to do about it. */
action?: { href: string; label: string };

dtsPropsFor.LinkRow:
/** Where a click anywhere on the row goes. */
href: string;
className?: string;
/** The row's `<td>` cells. */
children: React.ReactNode;

dtsPropsFor.NavLink:
href: string;
/** Every href in the menu, so only the best match highlights. */
hrefs?: string[];
/** Indented sub-entry. */
child?: boolean;
/** Right-aligned count pill. */
badge?: string | number;
/** Right-aligned admin-only lock glyph. */
lock?: boolean;
/** Icon element followed by the label text. */
children: React.ReactNode;

dtsPropsFor.SectionHomeLink:
href: string;
label: string;
/** Pre-rendered icon element. */
icon?: React.ReactNode;

dtsPropsFor.FilterRail:
/** Show me / Whose groups; each option is a link with an optional swatch colour and live count. Drawn at lg and above only. */
groups: { title: string; options: { href: string; label: string; active: boolean; swatch?: string; count?: number | string }[] }[];
/** One thing worth knowing about this list. */
note?: { title: string; body: string };
footnote?: string;
/** The list itself, to the right of the rail. */
children: React.ReactNode;
